/**
 * OFFLINE-ONLY ANTI-AUTOMATION LAB
 *
 * This file deliberately contains no HTTP, browser, Supabase, authentication,
 * credential, or filesystem-write code.  It is a reproducible adversarial
 * simulator: its only input is the checked-out authoritative game code.
 *
 * It must never be used to drive a live Race To Win session.  Its purpose is
 * to demonstrate the difference between a forged result (which the protocol
 * rejects) and a valid deterministic replay generated by automation.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import ts from "typescript";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..", "..");
const nativeRequire = createRequire(import.meta.url);
const moduleCache = new Map();

function loadTypeScript(path) {
  const absolutePath = resolve(path);
  const cached = moduleCache.get(absolutePath);
  if (cached) return cached.exports;

  const compiledModule = { exports: {} };
  moduleCache.set(absolutePath, compiledModule);
  const output = ts.transpileModule(readFileSync(absolutePath, "utf8"), {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
  }).outputText;
  new Function("exports", "module", "require", output)(compiledModule.exports, compiledModule, (name) => {
    if (name === "server-only") return {};
    if (name.startsWith(".")) return loadTypeScript(resolve(dirname(absolutePath), `${name}.ts`));
    return nativeRequire(name);
  });
  return compiledModule.exports;
}

const { RaceToWinSimulation } = loadTypeScript(resolve(root, "lib/game/race-to-win/simulation.ts"));
const { replayAuthoritativeProgress } = loadTypeScript(resolve(root, "lib/game/race-to-win/authoritative-replay.ts"));
const { GAMEPLAY_VERSION, DEFAULT_RACE_TO_WIN_CONFIG: config } = loadTypeScript(resolve(root, "lib/game/race-to-win/config.ts"));

/** Copy a simulation state without adding observation data unavailable to a browser. */
function cloneSimulation(value) {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(cloneSimulation);
  const copy = Object.create(Object.getPrototypeOf(value));
  for (const key of Reflect.ownKeys(value)) copy[key] = cloneSimulation(value[key]);
  return copy;
}

/** Tiny deterministic RNG used only to vary lab decision timing. */
function labRandom(seed) {
  let state = (seed ^ 0x9e3779b9) >>> 0;
  return () => {
    state ^= state << 13; state >>>= 0;
    state ^= state >>> 17; state >>>= 0;
    state ^= state << 5; state >>>= 0;
    return state / 0x1_0000_0000;
  };
}

function advance(simulation, ticks) {
  let snapshot = simulation.snapshot();
  for (let index = 0; index < ticks && snapshot.state === "running"; index += 1) {
    snapshot = simulation.step(config.fixedStepMs);
  }
  return snapshot;
}

/**
 * Searches only legal requestLaneChange actions against a cloned copy of the
 * exact client-visible simulation.  It does not alter collisions, timing,
 * traffic, score, seed, or server state.
 */
function choosePredictiveDirection(simulation, { horizon = 7, ticksPerDecision = 12, width = 12 } = {}) {
  let beam = [{ trial: cloneSimulation(simulation), first: 0, moves: 0 }];
  for (let depth = 0; depth < horizon; depth += 1) {
    const candidates = [];
    for (const node of beam) {
      for (const direction of [0, -1, 1]) {
        const trial = cloneSimulation(node.trial);
        if (direction !== 0 && !trial.requestLaneChange(direction)) continue;
        const snapshot = advance(trial, ticksPerDecision);
        if (snapshot.state !== "running") continue;
        candidates.push({
          trial,
          first: depth === 0 ? direction : node.first,
          moves: node.moves + Number(direction !== 0),
          distance: snapshot.metrics.distanceMeters,
        });
      }
    }
    if (candidates.length === 0) return 0;
    // Prefer a survivable future path with fewer gratuitous controls.  The
    // stable tie-break is deliberate so the deterministic baseline is
    // measurable; the noisy strategy below varies only its decision cadence.
    candidates.sort((left, right) => left.moves - right.moves || right.distance - left.distance || left.first - right.first);
    const seen = new Set();
    beam = candidates.filter((node) => {
      const player = node.trial.snapshot().player;
      const key = `${node.first}:${player.targetLaneIndex}:${player.laneX.toFixed(2)}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    }).slice(0, width);
  }
  return beam[0]?.first ?? 0;
}

function inputTimingSummary(inputs) {
  const intervals = inputs.slice(1).map((input, index) => input.atMs - inputs[index].atMs);
  const average = intervals.length === 0 ? null : intervals.reduce((sum, value) => sum + value, 0) / intervals.length;
  const variance = average === null ? null : intervals.reduce((sum, value) => sum + (value - average) ** 2, 0) / intervals.length;
  return {
    inputCount: inputs.length,
    distinctIntervals: new Set(intervals.map((value) => Math.round(value / 25) * 25)).size,
    meanIntervalMs: average === null ? null : Math.round(average),
    intervalStdDevMs: variance === null ? null : Math.round(Math.sqrt(variance)),
  };
}

/**
 * Run one fully local strategy.  `passive` and `cadenced` are deliberately
 * weak baselines. `predictive` models a source-aware deterministic bot.
 * `noisy-predictive` has varied timing, but is not labeled human-like: no
 * legitimate-human dataset has been collected.
 */
export function runCompetitiveBot({ seed, strategy, durationMs = 12 * 60_000 }) {
  if (!Number.isSafeInteger(seed) || seed < 0 || seed > 0xffff_ffff) throw new Error("seed must be a uint32");
  if (!Number.isSafeInteger(durationMs) || durationMs < config.fixedStepMs || durationMs > 20 * 60_000) throw new Error("durationMs must be 17–1,200,000 ms");
  if (!new Set(["passive", "cadenced", "predictive", "noisy-predictive"]).has(strategy)) throw new Error("unsupported offline lab strategy");

  const simulation = new RaceToWinSimulation({ seed, trafficVariantCount: 6 });
  const random = labRandom(seed);
  let nextDecisionAtTick = 0;
  let cadenceDirection = -1;
  let ticks = 0;
  simulation.start();
  let snapshot = simulation.snapshot();

  while (snapshot.state === "running" && snapshot.simulationTimeMs < durationMs) {
    if (strategy === "cadenced" && ticks % 36 === 0) {
      if (simulation.requestLaneChange(cadenceDirection)) cadenceDirection *= -1;
    }
    if ((strategy === "predictive" || strategy === "noisy-predictive") && ticks >= nextDecisionAtTick) {
      const direction = choosePredictiveDirection(simulation);
      if (direction !== 0) simulation.requestLaneChange(direction);
      // The noisy lab changes observation cadence (133–300 ms) and sometimes
      // waits for the next observation. It never invents a human distribution.
      const cadence = strategy === "noisy-predictive" ? 8 + Math.floor(random() * 11) : 12;
      nextDecisionAtTick = ticks + cadence;
    }
    snapshot = simulation.step(config.fixedStepMs);
    ticks += 1;
  }

  const inputs = simulation.runRecord().inputs;
  const replay = replayAuthoritativeProgress(GAMEPLAY_VERSION, seed, inputs, snapshot.simulationTimeMs);
  if (!replay || replay.state !== snapshot.state || replay.score !== snapshot.metrics.score || replay.distanceMillimeters !== Math.round(snapshot.metrics.distanceMeters * 1000)) {
    throw new Error("offline candidate did not reproduce under authoritative replay");
  }
  return Object.freeze({
    strategy,
    seed,
    targetDurationMs: durationMs,
    state: snapshot.state,
    elapsedMs: snapshot.simulationTimeMs,
    score: snapshot.metrics.score,
    distanceMillimeters: Math.round(snapshot.metrics.distanceMeters * 1000),
    checkpointsReached: Math.floor(snapshot.metrics.score / 1000),
    survivesTarget: snapshot.state === "running" && snapshot.simulationTimeMs >= durationMs,
    replayVerified: true,
    timing: inputTimingSummary(inputs),
  });
}

export function runLabBenchmark({ seeds = [1, 2, 3], durationMs = 12 * 60_000 } = {}) {
  if (!Array.isArray(seeds) || seeds.length === 0 || seeds.length > 20) throw new Error("benchmark accepts 1–20 local seeds");
  const strategies = ["passive", "cadenced", "predictive", "noisy-predictive"];
  const runs = strategies.flatMap((strategy) => seeds.map((seed) => runCompetitiveBot({ seed, strategy, durationMs })));
  const summary = Object.fromEntries(strategies.map((strategy) => {
    const subset = runs.filter((run) => run.strategy === strategy);
    return [strategy, {
      runs: subset.length,
      survivedTarget: subset.filter((run) => run.survivesTarget).length,
      crashed: subset.filter((run) => run.state === "crashed").length,
      highestScore: Math.max(...subset.map((run) => run.score)),
      averageScore: Math.round(subset.reduce((sum, run) => sum + run.score, 0) / subset.length),
    }];
  }));
  return Object.freeze({ offlineOnly: true, durationMs, seeds: [...seeds], runs, summary });
}

// `process.argv[1]` is normally relative when called as
// `node scripts/lab/competitive-bot.mjs`; normalize it so the offline guard
// and CLI benchmark are reliable on Windows as well as POSIX shells.
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  if (process.env.RTW_OFFLINE_ANTI_AUTOMATION_LAB !== "1") {
    throw new Error("Refusing to run: set RTW_OFFLINE_ANTI_AUTOMATION_LAB=1. This lab must stay offline.");
  }
  const benchmark = runLabBenchmark();
  process.stdout.write(`${JSON.stringify(benchmark, null, 2)}\n`);
}
